<?php declare(strict_types=1); require 'kms_functions.php'; $user=kms_require_role(['customer','seller','staff','manager','admin']); $title='Experts'; $msg='';$err=''; if($_SERVER['REQUEST_METHOD']==='POST'&&user_has_any_role(['manager','admin'])){verify_csrf();$uid=(int)($_POST['user_id']??0);$et=trim($_POST['expertise_title']??'');$bio=trim($_POST['bio']??'');$lv=$_POST['expertise_level']??'advanced';if(!$uid||!$et)$err='Employee dan keahlian wajib diisi.';else{$s=$pdoKms->prepare("INSERT INTO kms_experts(user_id,expertise_title,bio,expertise_level,is_available) VALUES(?,?,?, ?,1) ON DUPLICATE KEY UPDATE expertise_title=VALUES(expertise_title),bio=VALUES(bio),expertise_level=VALUES(expertise_level),is_available=1,updated_at=CURRENT_TIMESTAMP");$s->execute([$uid,$et,$bio?:null,$lv]);$msg='Profil expert tersimpan.';}} $employees=employee_users($pdo);$experts=$pdoKms->query("SELECT * FROM kms_experts WHERE is_available=1 ORDER BY expertise_level DESC, expertise_title")->fetchAll(); include 'kms_layout_top.php'; ?>
<div class="page-headline"><div><div class="eyebrow">EXPERT DIRECTORY</div><h1>Experts</h1><p>Temukan orang yang memiliki pengalaman dan keahlian tertentu.</p></div></div><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert alert-error"><?=e($err)?></div><?php endif;?><?php if(user_has_any_role(['manager','admin'])):?><section class="card expert-form-card"><h2>Add / Update Expert</h2><form method="POST"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-row"><div class="form-group"><label>Employee</label><select name="user_id" required><option value="">Choose</option><?php foreach($employees as $e1):?><option value="<?=$e1['id']?>"><?=e($e1['name'])?> — <?=e($e1['roles'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Expertise</label><input name="expertise_title" placeholder="Inventory Management" required></div><div class="form-group"><label>Level</label><select name="expertise_level"><option>expert</option><option selected>advanced</option><option>intermediate</option><option>beginner</option></select></div></div><div class="form-group"><label>Bio</label><textarea name="bio" rows="3"></textarea></div><button class="btn btn-primary">Save Expert Profile</button></form></section><?php endif;?><div class="expert-grid"><?php foreach($experts as $x):$name=kms_user_name($pdo,(int)$x['user_id']);?><article class="card expert-card"><div class="expert-avatar"><?=e(strtoupper(substr($name,0,1)))?></div><div class="expert-card-body"><div class="expert-level"><?=e($x['expertise_level'])?></div><h2><?=e($name)?></h2><strong><?=e($x['expertise_title'])?></strong><p><?=e($x['bio']?:'Belum ada bio.')?></p><div class="expert-footer"><span class="status-dot">Available</span><a class="text-link" href="knowledge.php?q=<?=urlencode($x['expertise_title'])?>">Related knowledge →</a></div></div></article><?php endforeach;?></div><?php if(!$experts):?><div class="empty-state large"><div class="empty-illustration">★</div><h2>Belum ada expert</h2><p>Manager atau admin dapat mendaftarkan profil expert di sini.</p></div><?php endif;?>
<?php include 'kms_layout_bottom.php'; ?>
